body.script:
let vh = window.innerHeight * 0.01;
document.documentElement.style.setProperty('--vh', `${vh}px`);
window.addEventListener('resize', () => {
  let vh = window.innerHeight * 0.01;
  document.documentElement.style.setProperty('--vh', `${vh}px`);
});

document.addEventListener('DOMContentLoaded', function() {
  const utmParams = ["utm_source", "utm_medium", "utm_campaign", "utm_term", "utm_content"];
  const gclidParam = "gclid";

  function captureAndSaveUtms() {
    const urlParams = new URLSearchParams(window.location.search);
    utmParams.forEach(param => {
      const value = urlParams.get(param);
      if (value) {
        localStorage.setItem(param, value);
      }
    });
  }

  function captureAndSaveGclid() {
    const urlParams = new URLSearchParams(window.location.search);
    const gclidValue = urlParams.get(gclidParam);
    if (gclidValue && !localStorage.getItem(gclidParam)) {
      localStorage.setItem(gclidParam, gclidValue);
    }
  }

  function deleteGclid() {
    localStorage.removeItem(gclidParam);
  }

  captureAndSaveUtms();

  const hasMarketingConsent = window.OnetrustActiveGroups && window.OnetrustActiveGroups.includes("C0003");
  if (hasMarketingConsent) {
    captureAndSaveGclid();
  } else {
    deleteGclid();
  }

  window.addEventListener('OneTrustGroupsUpdated', function() {
    const newHasMarketingConsent = window.OnetrustActiveGroups && window.OnetrustActiveGroups.includes("C0003");
    if (newHasMarketingConsent) {
      captureAndSaveGclid();
    } else {
      deleteGclid();
    }
  });
});

