 document.addEventListener('DOMContentLoaded', function() {
    console.log('DOM fully loaded and parsed');

    // Get a reference to the form on this page
    const form = document.querySelector('form');
    if (!form) {
        console.log('No form found on this page');
        return; // Exit if no form is found on this page
    }
    console.log('Form found:', form);

    const trackingParams = ["utm_source", "utm_medium", "utm_campaign", "utm_term", "utm_content", "gclid"];

    /**
     * Populates the form's hidden fields from values stored in localStorage.
     */
    function populateFormFromStorage() {
        trackingParams.forEach(param => {
            const value = localStorage.getItem(param);
            if (value) {
                const formField = form.querySelector(`input[name="${param}"]`);
                if (formField) {
                    formField.value = value;
                    console.log(`Populated ${param} with value: ${value}`);
                } else {
                    console.log(`No form field found for ${param}`);
                }
            } else {
                console.log(`No value in localStorage for ${param}`);
            }
        });
    }

    // Run the populate function on this page
    populateFormFromStorage();
});

