// Select all elements with the class 'email-input'
const emailInputs = document.querySelectorAll('.email');

emailInputs.forEach((emailInput) => {
  emailInput.addEventListener('invalid', (e) => {
    e.target.setCustomValidity('Please provide a business email');
  });

  emailInput.addEventListener('input', (e) => {
    e.target.setCustomValidity('');
  });
});

(function () {
  function init() {
    const form = document.querySelector('form[data-form="newsletter"]');
    if (!form) return;

    form.addEventListener("submit", function (e) {
      if (!window.grecaptcha) {
        e.preventDefault();
        alert("Captcha is still loading. Please try again.");
        return;
      }

      const token = grecaptcha.getResponse();
      if (!token) {
        e.preventDefault();
        alert("Please verify that you’re not a robot.");
        return;
      }
      // If checked, allow the form to submit normally to Pardot
    }, true);
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", init);
  } else {
    init();
  }
})();

(function () {
  const form = document.querySelector('form[data-form="newsletter"]');
  if (!form) return;

  form.addEventListener("submit", function (e) {
    const hp = form.querySelector('input[name="website"]');
    if (hp && hp.value.trim() !== "") {
      e.preventDefault(); // silently block bots
    }
  }, true);
})();
